import{_ as i,o as a,c as t,a2 as s}from"./chunks/framework.Cm6XCzck.js";const h=JSON.parse('{"title":"CodeFlowMu V2.1.2 Public Release Summary","description":"","frontmatter":{"title":"CodeFlowMu V2.1.2 Public Release Summary","date":"2026-08-30","updated":"2026-08-31","column":"research-evidence","category":"evidence","article_type":"release-summary","edition":"research-center","summary":"CodeFlowMu V2.1.2 is a Runtime boundary-safety patch focused on persistent idempotency for task creation, safe projection for ordinary Activity consumers, and Runtime verification of skill Session identity. This page provides a publicly accessible release summary, validation results, scope and evidence entry points.","lifecycle":"Published","publication_authorized":true},"headers":[],"relativePath":"en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary.md","filePath":"en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary.md","lastUpdated":1788145951000}'),n={name:"en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary.md"};function r(o,e,l,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[s('<p><a href="/joinwell52/zh/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary">中文版本</a></p><h1 id="codeflowmu-v2-1-2-public-release-summary" tabindex="-1">CodeFlowMu V2.1.2 Public Release Summary <a class="header-anchor" href="#codeflowmu-v2-1-2-public-release-summary" aria-label="Permalink to &quot;CodeFlowMu V2.1.2 Public Release Summary&quot;">​</a></h1><blockquote><p>Release date: 2026-08-30<br> Release type: Runtime boundary-safety patch<br> Public summary updated: 2026-08-31</p></blockquote><h2 id="what-is-codeflowmu" tabindex="-1">What is CodeFlowMu? <a class="header-anchor" href="#what-is-codeflowmu" aria-label="Permalink to &quot;What is CodeFlowMu?&quot;">​</a></h2><p>CodeFlowMu is a <strong>local-first multi-agent collaboration and digital-employee runtime</strong>. It does more than call models: agents with distinct responsibilities such as PM, DEV, QA, OPS and EVAL work continuously inside controlled workspaces, while the Runtime manages task objects, Sessions, tool calls, Activity, recovery and audit evidence.</p><p>Systems of this kind must survive long-running work, repeated wakeups, process recovery, Host interruptions and concurrency. That makes questions such as “did the action already happen?”, “which real Session did this call belong to?” and “which fields should a consumer be allowed to see?” product-level runtime boundaries rather than logging details.</p><h2 id="one-sentence-conclusion" tabindex="-1">One-sentence conclusion <a class="header-anchor" href="#one-sentence-conclusion" aria-label="Permalink to &quot;One-sentence conclusion&quot;">​</a></h2><p>V2.1.2 addresses three Runtime boundary problems:</p><ol><li><strong>Persistent idempotency for task creation</strong>: after response loss, concurrent retries or process recovery, the same stable business submission can recover the original creation result instead of creating a second TASK.</li><li><strong>Safe projection for ordinary Activity consumers</strong>: internal events can retain complete diagnostic facts while Web Panel, Activity API and Analytics receive only recursively allowlisted projections.</li><li><strong>Runtime verification of skill Session identity</strong>: a caller-supplied <code>session_id</code> is no longer treated as execution evidence until it is checked against Runtime SessionStore facts.</li></ol><h2 id="_1-task-creation-from-retry-after-failure-to-a-recoverable-creation-contract" tabindex="-1">1. Task creation: from “retry after failure” to a recoverable creation contract <a class="header-anchor" href="#_1-task-creation-from-retry-after-failure-to-a-recoverable-creation-contract" aria-label="Permalink to &quot;1. Task creation: from “retry after failure” to a recoverable creation contract&quot;">​</a></h2><p>For callers that need strong idempotency, V2.1.2 adds a stable <code>client_submission_id</code>, canonical <code>request_digest</code>, a pre-creation reservation and a machine-readable creation receipt.</p><p>The core relation is:</p><p><code>client_submission_id → request_digest → task_id / task_path → creation_result</code></p><p>Retries with the same submission identity and the same request digest reuse the original result. Reusing the same submission identity with a different digest returns <code>conflict</code> and creates no additional TASK. The creation process is persisted as:</p><p><code>reserved → task_created → committed</code></p><p>This covers the window in which a TASK has already been persisted but the success response is lost, as well as intermediate-state recovery.</p><p>Key independent-QA observations:</p><ul><li>A2 response-loss retry: final TASK count 1; <code>task_id</code> unchanged; second call returned <code>reused / action_taken=false</code>.</li><li>A4 eight-way concurrency: <code>created=1 / reused=7</code>; one authoritative <code>task_id</code>; final TASK count 1.</li></ul><p>Public evidence: <a href="/joinwell52/en/research/evidence/2026-08-28-response-loss-idempotency">Response Loss and Per-Tool Idempotency</a>.</p><h2 id="_2-activity-retaining-internal-evidence-does-not-mean-every-consumer-receives-every-field" tabindex="-1">2. Activity: retaining internal evidence does not mean every consumer receives every field <a class="header-anchor" href="#_2-activity-retaining-internal-evidence-does-not-mean-every-consumer-receives-every-field" aria-label="Permalink to &quot;2. Activity: retaining internal evidence does not mean every consumer receives every field&quot;">​</a></h2><p>V2.1.2 separates internal Activity fact objects from ordinary consumer objects.</p><p>Instead of copying a complete object and deleting a few known fields, the server reconstructs consumer-specific projections from recursive allowlists. <code>payload.raw</code>, unknown fields and unknown nested values are excluded from ordinary results by default. Approved relational fields such as task, thread, session, event and <code>projected_summary</code> remain available.</p><p>Raw internal events are still retained for explicitly authorized diagnostic paths. The change therefore establishes a consumer boundary rather than deleting diagnostic facts.</p><p>Key independent-QA B1 observations:</p><ul><li>a unique marker present only in raw appeared <strong>0 times</strong> in the ordinary projection;</li><li><code>raw_present=false</code>;</li><li>event_type, task_id, session_id and <code>projected_summary</code> remained present.</li></ul><p>Public evidence: <a href="/joinwell52/en/research/evidence/2026-08-28-event-consumer-visibility">Event Consumer Visibility</a>.</p><h2 id="_3-session-identity-claims-must-return-to-runtime-authority" tabindex="-1">3. Session: identity claims must return to Runtime authority <a class="header-anchor" href="#_3-session-identity-claims-must-return-to-runtime-authority" aria-label="Permalink to &quot;3. Session: identity claims must return to Runtime authority&quot;">​</a></h2><p>V2.1.2 no longer upgrades a caller-supplied <code>session_id</code> directly into trusted execution identity. The Runtime checks SessionStore against:</p><ul><li>task_id;</li><li>thread_key;</li><li>session_id;</li><li>agent;</li><li>caller;</li><li>whether the Session exists and is in an acceptable state.</li></ul><p>The resulting evidence semantics are explicit:</p><ul><li><code>verified</code>: Runtime-authoritative Session facts support the binding;</li><li><code>sessionless/not_applicable</code>: the operation is legitimately sessionless by design and has a Runtime reason;</li><li><code>invalid_claim</code>: the Session claim conflicts with Runtime facts and is preserved as a negative audit fact rather than upgraded into trusted evidence.</li></ul><p>Independent QA C1 used an actual SessionStore registration and verified consistency across task/thread/session/agent/caller, with journal integrity verification passing.</p><p>Public evidence: <a href="/joinwell52/en/research/evidence/2026-08-28-skill-session-evidence">Skill and Session Evidence Chain</a>.</p><h2 id="release-validation" tabindex="-1">Release validation <a class="header-anchor" href="#release-validation" aria-label="Permalink to &quot;Release validation&quot;">​</a></h2><p>Final V2.1.2 release validation recorded:</p><ul><li>Runtime: <strong>1842 pass / 0 fail / 1 skip</strong>;</li><li>Shell: <strong>1037 pass / 0 fail / 0 skip</strong>;</li><li>V2.1.1 and V2.1.2 same-protocol critical matrices, each repeated for 10 rounds: Runtime <strong>1630/1630</strong>, Shell <strong>550/550</strong>;</li><li>typecheck, Shell build, installer contract, rules and version consistency all passed.</li></ul><p>These are actual results for the release test sets. They are not a “reliability rate”, “security rate” or “evidence trust rate”. Earlier failed release attempts remain part of the record, including field over-pruning, lockfile issues and the independent Open Edition build boundary.</p><h2 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h2><ul><li>CodeFlowMu: V2.1.2</li><li>Runtime: V2.1.2</li><li>Shell: V2.1.2</li><li>Protocol: V1.1.1 (unchanged)</li><li>Mobile PWA / Service Worker cache: V1.0.75 (unchanged)</li><li>Mobile API: V1.3.4 (unchanged)</li><li>Gateway: V1.0.12 (unchanged)</li></ul><p>No data migration is required. Existing TASK, REPORT, Session and Activity files do not need bulk rewriting.</p><p>Legacy callers that omit <code>client_submission_id</code> continue to use the legacy creation path, but they do not receive strong idempotency across response loss and process recovery. Ordinary Activity consumers that previously depended on unregistered raw/unknown fields must migrate to public projected fields. Consumers of skill invocation evidence must also stop treating the mere presence of a <code>session_id</code> string as equivalent to <code>verified</code>.</p><h2 id="what-this-release-does-not-claim" tabindex="-1">What this release does not claim <a class="header-anchor" href="#what-this-release-does-not-claim" aria-label="Permalink to &quot;What this release does not claim&quot;">​</a></h2><p>V2.1.2 does not prove that:</p><ul><li>every Agent tool is safe to retry;</li><li>every Host, real LAN/Gateway deployment, browser profile or production project has been covered;</li><li>the entire Runtime is free of all information-disclosure risk;</li><li><code>session_binding=verified</code> proves that skill advice, code or task results are correct;</li><li>Open Dev Team Edition has been released in sync.</li></ul><p>The one Windows symlink permission skip, existing dependency warnings, some environment warnings and uncovered real-deployment scopes remain explicitly recorded.</p><h2 id="about-source-code-and-original-release-material" tabindex="-1">About source code and original release material <a class="header-anchor" href="#about-source-code-and-original-release-material" aria-label="Permalink to &quot;About source code and original release material&quot;">​</a></h2><p>The current CodeFlowMu product mother repository is private. V2.1.2 implementation source, complete independent-QA logs, R3 release logs and release receipts are restricted first-party material and are not used as public reading links.</p><p>This page exists to expose the <strong>version facts, validation results, scope and limitations</strong> directly relevant to the public research articles in a stable, publicly accessible form. Public evidence pages also provide sanitized fixtures, readers/checks or source mappings. They are not presented as a substitute capable of fully rerunning the private Runtime.</p><h2 id="related-articles" tabindex="-1">Related articles <a class="header-anchor" href="#related-articles" aria-label="Permalink to &quot;Related articles&quot;">​</a></h2><ul><li><a href="/joinwell52/en/engineering/2026-08-28-response-loss-idempotency">Engineering Record I: After Response Loss, Reliable Retry Starts with a Persistent Idempotency Boundary</a></li><li><a href="/joinwell52/en/digital-employee/2026-08-28-skill-session-evidence">Engineering Record II: Session Identity Cannot Be Self-Asserted — Building a Verifiable Execution-Evidence Boundary</a></li><li><a href="/joinwell52/en/engineering/2026-08-28-event-consumer-visibility">Engineering Record III: An Event Happened — But Who Should See What? Designing Safe Activity Projection</a></li></ul>',50)])])}const m=i(n,[["render",r]]);export{h as __pageData,m as default};
